import{deviceEventSchema}from"@/features/integrations/schemas";import{executeIdempotent,ExternalApiError,withExternalApi}from"@/features/integrations/services/externalApi";import{ingestAttendanceDeviceEvent}from"@/features/integrations/services/attendanceDeviceService";import{parseWithSchema}from"@/lib/api/validation";
export async function POST(request:Request){return withExternalApi(request,{scope:"attendance.write",category:"attendance.write"},async principal=>{const length=Number(request.headers.get("content-length")??0);if(length>1048576)throw new ExternalApiError("PAYLOAD_TOO_LARGE","Payload vượt quá 1 MB.",413);const raw=await request.text();if(raw.length>1048576)throw new ExternalApiError("PAYLOAD_TOO_LARGE","Payload vượt quá 1 MB.",413);let value:unknown;try{value=JSON.parse(raw);}catch{value=null;}const input=parseWithSchema(deviceEventSchema,value);return executeIdempotent(principal,"attendance-device-events",request.headers.get("idempotency-key"),raw,()=>ingestAttendanceDeviceEvent(input));});}
